tokens.css:
--color-bg: #1c1214;
--color-surface: #2a1e21;
--color-text: #f6efe9;
--color-text-muted: #a89a94;
--color-border: #4a3b3e;
--color-primary: #b23736;
--color-on-primary: #ffffff;
--color-accent: #d9a441;
--color-on-accent: #1c1214;
--font-display: "Italiana", Georgia, serif;
--font-body: "Hanken Grotesk", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 17px;
--text-lg: 21px;
--text-xl: 27px;
--text-2xl: 33px;
--text-3xl: 42px;
--radius-control: 4px;
--radius-card: 8px;
--space-section: 112px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
